CREATE TABLE IF NOT EXISTS youtube_like_monitors (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), video_id TEXT NOT NULL, claim_id TEXT NOT NULL, started_at INTEGER NOT NULL, deadline_at INTEGER NOT NULL, last_checked_at INTEGER, status TEXT NOT NULL CHECK(status IN ('pending','confirmed','reversed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX IF NOT EXISTS idx_youtube_like_monitors_status ON youtube_like_monitors(status, deadline_at); CREATE INDEX IF NOT EXISTS idx_youtube_like_monitors_user ON youtube_like_monitors(user_id, status);